//! Correctness of the scalar reference forward pass against the
//! `transformers` golden reference.
//!
//! The fixture (`fixtures/oracle-tiny/`) is a tiny random-weight
//! DeepSeek-V3-architecture checkpoint generated by `engine_bench`.
//! `reference.json` was produced by `tools/make_reference.py`, which ran
//! the same checkpoint through `DeepseekV3ForCausalLM`. Passing here means:
//! MLA attention, interleaved partial RoPE, the sigmoid `noaux_tc` router
//! (including group limitation and correction bias), shared experts and
//! the dense prefix all agree with upstream, token-exactly.

use std::path::PathBuf;

use serde::Deserialize;

#[derive(Deserialize)]
struct Reference {
    prompt_ids: Vec<usize>,
    full_ids: Vec<usize>,
    tf_pred: Vec<usize>,
    tf_logits: Vec<Vec<f32>>,
}

fn fixture_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("fixtures/oracle-tiny")
}

fn load_reference() -> Reference {
    let bytes = std::fs::read(fixture_dir().join("reference.json"))
        .expect("reference.json missing — see engine-bench/tools/make_reference.py");
    serde_json::from_slice(&bytes).expect("bad reference.json")
}

#[test]
fn teacher_forcing_matches_transformers() {
    let reference = load_reference();
    let model = deepseek_moe::loader::load_model(fixture_dir()).expect("load fixture");
    let logits = model.forward(&reference.full_ids).expect("forward");

    let seq = reference.full_ids.len();
    assert_eq!(logits.shape, vec![seq, model.cfg.vocab_size]);

    // Full-precision comparison: max abs logit error across every position.
    let mut max_err = 0.0f32;
    for (s, ref_row) in reference.tf_logits.iter().enumerate() {
        for (ours, theirs) in logits.row(s).iter().zip(ref_row) {
            max_err = max_err.max((ours - theirs).abs());
        }
    }
    // f32 forward with different accumulation order than torch; the
    // reference logits are also rounded to 1e-6 in the json.
    eprintln!("max logit error vs transformers: {max_err:e}");
    assert!(max_err < 1e-3, "max logit error vs transformers: {max_err}");

    // Token-exact: argmax at every position (the tf_pred check).
    let ours_pred: Vec<usize> = (0..seq).map(|s| argmax(logits.row(s))).collect();
    assert_eq!(
        ours_pred, reference.tf_pred,
        "teacher-forcing argmax mismatch"
    );
}

#[test]
fn greedy_decode_matches_transformers() {
    let reference = load_reference();
    let model = deepseek_moe::loader::load_model(fixture_dir()).expect("load fixture");
    let max_new = reference.full_ids.len() - reference.prompt_ids.len();
    let ours = model
        .greedy_decode(&reference.prompt_ids, max_new, &[])
        .expect("decode");
    assert_eq!(ours, reference.full_ids, "greedy continuation mismatch");
}

/// The golden reference.json is only valid for the exact fixture weights.
/// The generator is platform-deterministic (integer PCG32 + Irwin–Hall,
/// no libm in the generation path), so regenerating must reproduce the
/// checked-in fixture byte-for-byte; drift here means someone changed the
/// generator without regenerating reference.json.
#[test]
fn fixture_matches_generator() {
    let tmp = tempfile::tempdir().unwrap();
    engine_bench::generate_oracle(tmp.path(), &engine_bench::OracleSpec::default()).unwrap();
    let regenerated = std::fs::read(tmp.path().join("model.safetensors")).unwrap();
    let fixture = std::fs::read(fixture_dir().join("model.safetensors")).unwrap();
    assert!(
        regenerated == fixture,
        "fixture safetensors differs from generator output — regenerate the \
         fixture AND reference.json (see tools/make_reference.py)"
    );
}

fn argmax(v: &[f32]) -> usize {
    let mut best = 0;
    for (i, &x) in v.iter().enumerate() {
        if x > v[best] {
            best = i;
        }
    }
    best
}
